sp_widget.script:
(function() { data.sections = []; data.templateId = $sp.getParameter("template_id") || "";
  try { if (!data.templateId) return;
    if (input && input.action === "add_section") { var sGr = new GlideRecord("x_1433041_identi_0_section"); sGr.initialize(); sGr.setValue("template", data.templateId); sGr.setValue("name", input.section_name); sGr.setValue("order", input.section_order || 100); sGr.insert(); }
    var gr = new GlideRecord("x_1433041_identi_0_section"); gr.addQuery("template", data.templateId); gr.orderBy("order"); gr.setLimit(50); gr.query();
    while (gr.next()) { data.sections.push({ sys_id: gr.getValue("sys_id"), name: gr.getValue("name"), order: gr.getValue("order") }); }
  } catch (e) { gs.error("IBAR Section Builder widget error: " + e.message); }
})();
